import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.C4u7U0Dw.js";const b=JSON.parse('{"title":"第 6 章 记忆系统：让 AI 越来越懂你","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md"};function i(o,t,l,r,h,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="第-6-章-记忆系统-让-ai-越来越懂你" tabindex="-1">第 6 章 记忆系统：让 AI 越来越懂你 <a class="header-anchor" href="#第-6-章-记忆系统-让-ai-越来越懂你" aria-label="Permalink to &quot;第 6 章 记忆系统：让 AI 越来越懂你&quot;">​</a></h1><blockquote><p>本章目标：理解记忆系统的原理与用法——四种记忆类型、记忆如何形成、什么该记什么不该记，以及记忆与文件的正确分工。<strong>你花两分钟喂我的记忆，未来每天都能省两分钟以上的沟通成本。</strong></p></blockquote><h2 id="_6-1-为什么需要记忆" tabindex="-1">6.1 为什么需要记忆 <a class="header-anchor" href="#_6-1-为什么需要记忆" aria-label="Permalink to &quot;6.1 为什么需要记忆&quot;">​</a></h2><p>每次对话结束，如果我什么都不记得，你就得把项目背景、你的偏好、你的坑，重新讲一遍。这很蠢。</p><p>我有<strong>持久化记忆</strong>：存在你项目对应的 memory 目录里，跨会话保留。下次见面，我还记得你是谁、在做什么、喜欢什么风格。</p><h3 id="_6-1-1-有记忆-vs-没记忆" tabindex="-1">6.1.1 有记忆 vs 没记忆 <a class="header-anchor" href="#_6-1-1-有记忆-vs-没记忆" aria-label="Permalink to &quot;6.1.1 有记忆 vs 没记忆&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>没记忆</th><th>有记忆</th></tr></thead><tbody><tr><td>第二次见面</td><td>重新自我介绍</td><td>&quot;你好，上回我们完成了 CSV 合并，这次做什么？&quot;</td></tr><tr><td>你提要求</td><td>每次都重新说一遍偏好</td><td>&quot;用户偏好中文简洁文档，自动执行&quot;</td></tr><tr><td>项目交接</td><td>背景全靠你解释</td><td>项目决策、术语、口径都在记忆里</td></tr></tbody></table><h2 id="_6-2-记忆的四种类型" tabindex="-1">6.2 记忆的四种类型 <a class="header-anchor" href="#_6-2-记忆的四种类型" aria-label="Permalink to &quot;6.2 记忆的四种类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>记什么</th><th>示例</th></tr></thead><tbody><tr><td><strong>user</strong></td><td>关于你这个人</td><td>用户是产品经理，偏好中文简洁文档</td></tr><tr><td><strong>feedback</strong></td><td>你的反馈与偏好</td><td>&quot;不要用被动语态&quot;&quot;先给结论&quot;</td></tr><tr><td><strong>project</strong></td><td>项目背景</td><td>这个项目是 MomaWork 白皮书</td></tr><tr><td><strong>reference</strong></td><td>参考资料</td><td>蓝皮书结构参考、指令模板</td></tr></tbody></table><h3 id="_6-2-1-记忆的物理形态" tabindex="-1">6.2.1 记忆的物理形态 <a class="header-anchor" href="#_6-2-1-记忆的物理形态" aria-label="Permalink to &quot;6.2.1 记忆的物理形态&quot;">​</a></h3><p>每一条记忆 = 一个 Markdown 文件（带 frontmatter）+ 一条 MEMORY.md 索引：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: 用户偏好中文简洁文档</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 写作风格偏好</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type: user</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">用户是产品经理，偏好中文、简洁、先给结论的文档风格。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">关键特性</p><p><strong>记忆是透明的文件，你可以随时查看、修改、删除。</strong> 记忆不是黑盒——你能看到我记住了什么，也能纠正或清除。</p></div><h2 id="_6-3-记忆是怎么形成的" tabindex="-1">6.3 记忆是怎么形成的 <a class="header-anchor" href="#_6-3-记忆是怎么形成的" aria-label="Permalink to &quot;6.3 记忆是怎么形成的&quot;">​</a></h2><p>记忆有三个来源：</p><h3 id="_6-3-1-你显式要求-最可靠" tabindex="-1">6.3.1 你显式要求（最可靠） <a class="header-anchor" href="#_6-3-1-你显式要求-最可靠" aria-label="Permalink to &quot;6.3.1 你显式要求（最可靠）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：记住我偏好 X</span></span>
<span class="line"><span>我：已保存到记忆系统。</span></span></code></pre></div><h3 id="_6-3-2-我主动沉淀-需你的确认" tabindex="-1">6.3.2 我主动沉淀（需你的确认） <a class="header-anchor" href="#_6-3-2-我主动沉淀-需你的确认" aria-label="Permalink to &quot;6.3.2 我主动沉淀（需你的确认）&quot;">​</a></h3><p>在合作中发现的稳定偏好，我会主动记下来——但重要的、影响大的记忆，我会先跟你确认：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我：注意到你每次都要求 Excel 格式，要我把这条记下来吗？</span></span>
<span class="line"><span>你：好</span></span></code></pre></div><h3 id="_6-3-3-你纠正我-feedback-更新" tabindex="-1">6.3.3 你纠正我（feedback 更新） <a class="header-anchor" href="#_6-3-3-你纠正我-feedback-更新" aria-label="Permalink to &quot;6.3.3 你纠正我（feedback 更新）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：我说过不要用被动语态</span></span>
<span class="line"><span>我：已更新反馈记忆，下次注意。</span></span></code></pre></div><blockquote><p>你可以随时说：&quot;把……忘了&quot; / &quot;记住……&quot;，我都能处理。</p></blockquote><h2 id="_6-4-记忆的正确用法" tabindex="-1">6.4 记忆的正确用法 <a class="header-anchor" href="#_6-4-记忆的正确用法" aria-label="Permalink to &quot;6.4 记忆的正确用法&quot;">​</a></h2><h3 id="_6-4-1-要记的" tabindex="-1">6.4.1 要记的 <a class="header-anchor" href="#_6-4-1-要记的" aria-label="Permalink to &quot;6.4.1 要记的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>示例</th><th>原因</th></tr></thead><tbody><tr><td>稳定偏好</td><td>语言、风格、格式</td><td>每次协作都要用到</td></tr><tr><td>项目关键决策</td><td>为什么这么设计</td><td>避免反复解释与反复推翻</td></tr><tr><td>工作上下文</td><td>在做什么、下一步是什么</td><td>跨会话无缝衔接</td></tr></tbody></table><h3 id="_6-4-2-不要记的" tabindex="-1">6.4.2 不要记的 <a class="header-anchor" href="#_6-4-2-不要记的" aria-label="Permalink to &quot;6.4.2 不要记的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>示例</th><th>原因</th></tr></thead><tbody><tr><td>一次性临时信息</td><td>某个临时任务的数据</td><td>任务完成就该消失</td></tr><tr><td><strong>敏感信息</strong></td><td>密码、密钥、token</td><td><strong>记忆文件是明文，请勿存放！</strong></td></tr><tr><td>频繁变动的数据</td><td>实时价格、库存</td><td>应该放项目文件，而不是记忆里</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">安全警告</p><p><strong>密码、API Key、Token 等机密永远不要写进项目文件或记忆文件。</strong> 如果你需要我处理机密信息，用安全的方式传递（如环境变量、一次性会话），用完即弃。</p></div><h2 id="_6-5-记忆与文件的分工" tabindex="-1">6.5 记忆与文件的分工 <a class="header-anchor" href="#_6-5-记忆与文件的分工" aria-label="Permalink to &quot;6.5 记忆与文件的分工&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记忆    → 关于&quot;怎么做&quot;的稳定知识（偏好、方法、约定）</span></span>
<span class="line"><span>文件    → 关于&quot;做了什么&quot;的具体内容（产物、数据、文档）</span></span></code></pre></div><h3 id="_6-5-1-判断口诀" tabindex="-1">6.5.1 判断口诀 <a class="header-anchor" href="#_6-5-1-判断口诀" aria-label="Permalink to &quot;6.5.1 判断口诀&quot;">​</a></h3><ul><li><strong>会反复用到、跨任务有效</strong> → 记忆；</li><li><strong>任务产出、随时查证</strong> → 项目文件；</li><li><strong>会变化、需要版本管理</strong> → 项目文件（配合 git）。</li></ul><p>一句话：<strong>文件是仓库，记忆是说明书。</strong></p><h3 id="_6-5-2-一个完整例子" tabindex="-1">6.5.2 一个完整例子 <a class="header-anchor" href="#_6-5-2-一个完整例子" aria-label="Permalink to &quot;6.5.2 一个完整例子&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记忆（说明书）：用户写周报偏好表格 + 先结论后展开</span></span>
<span class="line"><span>文件（仓库）：  docs/周报/2026-W33.md（具体那周的周报内容）</span></span></code></pre></div><p>下次写周报：我从记忆里知道格式偏好，从文件里读取上周内容，一次成型。</p><h2 id="_6-6-记忆系统的进阶方向" tabindex="-1">6.6 记忆系统的进阶方向 <a class="header-anchor" href="#_6-6-记忆系统的进阶方向" aria-label="Permalink to &quot;6.6 记忆系统的进阶方向&quot;">​</a></h2><p>本章讲的是&quot;记忆的基础使用&quot;。记忆还有进阶玩法：</p><table tabindex="0"><thead><tr><th>进阶方向</th><th>说明</th><th>对应章节</th></tr></thead><tbody><tr><td>项目专属记忆</td><td>为每个项目建立独立的记忆空间</td><td>第 13、20 章</td></tr><tr><td>团队共享记忆</td><td>团队协作时共享上下文</td><td>第 16 章</td></tr><tr><td>记忆卫生</td><td>定期清理过期、错误记忆</td><td>第 20 章</td></tr></tbody></table><h2 id="_6-7-本章练习" tabindex="-1">6.7 本章练习 <a class="header-anchor" href="#_6-7-本章练习" aria-label="Permalink to &quot;6.7 本章练习&quot;">​</a></h2><ol><li>告诉我 3 条关于你的稳定信息（身份、偏好、常用格式），让我记住。</li><li>让我查看当前的 MEMORY.md 索引，确认记忆已保存。</li><li>故意说错一条，再纠正我，看看 feedback 记忆如何更新。</li><li>检查你的记忆目录，确认没有敏感信息混入；如有，删除它。</li></ol><hr><blockquote><p>小结：记忆系统让我从&quot;每次都是陌生人&quot;变成&quot;越用越懂你的老搭档&quot;。<strong>记忆是透明的、可控的、可纠正的</strong>——你花两分钟喂我的记忆，未来每天都能省两分钟以上的沟通成本。下一章，进入长任务的战场：计划模式。</p></blockquote>`,44)])])}const u=a(n,[["render",i]]);export{b as __pageData,u as default};
